	RealType percent(VarType value, VarType s, VarType e, BoolType limit)
	{
		if (s == e)
			return (value < s);
		if (limit)
			return clamp((value - s) / (e - s), IntType(0), IntType(1));
		else
			return (value - s) / (e - s);
		
		return 0.0;
	}
	
